    HaceV1HACEFEATURECQBURSTPos = 28
    HaceV1HACEFEATURECQBURSTMsk = 0x1 << 28
    // CTR64BIT AES/DES CTR counter width: 0=32-bit, 1=64-bit.
    HaceV1HACEFEATURECTR64BITPos = 29
    HaceV1HACEFEATURECTR64BITMsk = 0x1 << 29
